operations.ancien_texte:
if ground_truth is None:
    m_rap = re.search(r'1/([2-9]|[1-9]\d+)', question)
    if m_rap and int(m_rap.group(1)) != 2:
        m_n = re.search(r'n\s*=\s*(\d+)', question, re.IGNORECASE)
        n_rnt = int(m_n.group(1)) if m_n else 10
        rnt = self.core.reconstruire_rapport_non_typique('1/%s' % m_rap.group(1), n=n_rnt)
        if rnt and rnt.get('premier') is not None:
            ground_truth = {
                'position': n_rnt,
                'prime': rnt['premier'],
                'n': n_rnt,
                'num_terms': n_rnt,
                'ratio': '1/%s' % m_rap.group(1),
                'note': rnt.get('note'),
            }

operations.nouveau_texte:
if ground_truth is None:
    ratios_trouves = re.findall(r'1/(?:[2-9]|[1-9]\d+)', question)
    if ratios_trouves:
        m_n = re.search(r'n\s*=\s*(\d+)', question, re.IGNORECASE)
        n_rnt = int(m_n.group(1)) if m_n else 10
        if len(ratios_trouves) > 1:
            res_multi = self.core.traiter_multi_ratios(ratios_trouves, n=n_rnt)
            ground_truth = {
                'position': n_rnt,
                'n': n_rnt,
                'num_terms': n_rnt,
                'ratios': ratios_trouves,
                'multi_results': res_multi,
            }
        else:
            rnt = self.core.reconstruire_rapport_non_typique(ratios_trouves[0], n=n_rnt)
            if rnt and rnt.get('premier') is not None:
                ground_truth = {
                    'position': n_rnt,
                    'prime': rnt['premier'],
                    'n': n_rnt,
                    'num_terms': n_rnt,
                    'ratio': ratios_trouves[0],
                    'note': rnt.get('note'),
                }
